BEGIN;
-- In progress: complete source adapters and verification before application.
CREATE SCHEMA erp_reports_private;
REVOKE ALL ON SCHEMA erp_reports_private FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE public.erp_saved_reports(cafe_id uuid NOT NULL REFERENCES public.cafes(id),id uuid NOT NULL DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(btrim(name)) BETWEEN 1 AND 150),family text NOT NULL,definition jsonb NOT NULL CHECK(jsonb_typeof(definition)='object'),revision integer NOT NULL DEFAULT 1,created_by uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(cafe_id,id));
CREATE TABLE public.erp_report_events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,cafe_id uuid NOT NULL REFERENCES public.cafes(id),record_id uuid NOT NULL,action text NOT NULL,actor uuid NOT NULL REFERENCES auth.users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE erp_reports_private.requests(cafe_id uuid NOT NULL,id uuid NOT NULL,actor uuid NOT NULL,command jsonb NOT NULL,result jsonb NOT NULL,PRIMARY KEY(cafe_id,id));
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON erp_reports_private.requests FOR EACH ROW EXECUTE FUNCTION brand_finance_private.immutable();
CREATE TRIGGER immutable BEFORE UPDATE OR DELETE ON public.erp_report_events FOR EACH ROW EXECUTE FUNCTION brand_finance_private.immutable();
ALTER TABLE public.erp_saved_reports ENABLE ROW LEVEL SECURITY;ALTER TABLE public.erp_report_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.erp_saved_reports,public.erp_report_events FROM PUBLIC,anon,authenticated,service_role;
CREATE TABLE erp_reports_private.catalog(id text PRIMARY KEY,family text NOT NULL,title text NOT NULL,source text NOT NULL,definition jsonb NOT NULL);
CREATE TABLE erp_reports_private.sources(id text PRIMARY KEY,title text NOT NULL,domain text NOT NULL,columns jsonb NOT NULL DEFAULT '[]');
DO $$DECLARE d text[];BEGIN d:=erp_access_private.domains();IF NOT('reports'=ANY(d)) THEN d:=array_append(d,'reports');EXECUTE format('CREATE OR REPLACE FUNCTION erp_access_private.domains() RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path='''' AS $f$SELECT %L::text[]$f$',d);END IF;UPDATE public.erp_roles SET permissions=permissions||jsonb_build_object('reports',jsonb_build_object('read',false,'create',false,'update',false,'delete',false,'approve',false,'settings',false,'files',false)) WHERE NOT(permissions?'reports');END $$;
CREATE FUNCTION erp_reports_private.authorize(c uuid,a text DEFAULT 'read') RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE r text;BEGIN r:=brand_finance_private.role_for(c);IF coalesce(r,'') NOT IN('owner','manager','accountant','auditor','warehouse') OR(a<>'read' AND r IN('auditor','warehouse')) THEN RAISE EXCEPTION 'لا تملك صلاحية التقارير المطلوبة' USING ERRCODE='42501';END IF;PERFORM erp_access_private.assert_allowed(c,'reports',a);RETURN r;END $$;
CREATE FUNCTION erp_reports_private.authorize_source(c uuid,s text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE d text;r text;BEGIN
 r:=erp_reports_private.authorize(c);SELECT domain INTO d FROM erp_reports_private.sources WHERE id=s;IF NOT FOUND THEN RAISE EXCEPTION 'مصدر التقرير غير متاح';END IF;
 IF r='warehouse' AND d NOT IN('inventory','manufacturing') THEN RAISE EXCEPTION 'مصدر التقرير خارج صلاحية المخازن' USING ERRCODE='42501';END IF;
 IF d IN('settings','activity') THEN IF r<>'owner' THEN RAISE EXCEPTION 'هذا التقرير متاح لمالك العلامة' USING ERRCODE='42501';END IF;ELSIF d<>'sales' THEN PERFORM erp_access_private.assert_allowed(c,d,'read');END IF;
 IF s='cost-centers' THEN PERFORM erp_access_private.assert_allowed(c,'finance','read');PERFORM erp_access_private.assert_allowed(c,'purchases','read');END IF;
END $$;
CREATE FUNCTION erp_reports_private.fact(i text,d date,p jsonb) RETURNS jsonb LANGUAGE sql IMMUTABLE SET search_path='' AS $$SELECT jsonb_build_object('id',i,'date',d,'count',1)||p$$;
CREATE FUNCTION erp_reports_private.document_branch(c uuid,d jsonb) RETURNS jsonb LANGUAGE sql STABLE SET search_path='' AS $$SELECT jsonb_build_object('branchId',nullif(d->>'branch_id',''),'branch',coalesce((SELECT name FROM public.branches WHERE cafe_id=c AND id::text=d->>'branch_id'),''))$$;
CREATE FUNCTION erp_reports_private.financial_facts(c uuid,s text,f date,t date) RETURNS SETOF jsonb LANGUAGE plpgsql SET search_path='' AS $$BEGIN
 IF s IN('sales','purchase-documents') THEN
  RETURN QUERY SELECT erp_reports_private.fact(d.id::text,(d.created_at AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('number',coalesce(to_jsonb(e)->>'display_number',d.number::text),'name',coalesce(p.name,''),'customer',CASE WHEN p.kind='customer' THEN p.name ELSE '' END,'customerId',CASE WHEN p.kind='customer' THEN p.id END,'supplier',CASE WHEN p.kind='supplier' THEN p.name ELSE '' END,'supplierId',CASE WHEN p.kind='supplier' THEN p.id END,'employeeId',d.created_by,'employee',coalesce(st.name,''),'kind',d.kind,'note',d.note,'net',d.subtotal-d.discount,'tax',d.tax,'amount',d.total,'paid',coalesce((state->>'paid')::numeric,d.paid),'outstanding',coalesce((state->>'outstanding')::numeric,0),'refunded',coalesce((state->>'refunded_total')::numeric,0),'status',CASE WHEN coalesce((state->>'refunded')::boolean,false) THEN 'refunded' WHEN coalesce((state->>'outstanding')::numeric,0)<=0 THEN 'paid' WHEN coalesce((state->>'paid')::numeric,d.paid)>0 THEN 'partial' ELSE 'unpaid' END,'currency','SAR','electronicStatus',coalesce(to_jsonb(e)->>'e_invoice_status','not_submitted'),'href',CASE WHEN d.kind='sale' THEN '/dashboard/finance?section=sales&view=invoice&invoice=' ELSE '/dashboard/system/purchases/invoices/' END||d.id::text)||erp_reports_private.document_branch(c,to_jsonb(d)))
  FROM public.bf_documents d LEFT JOIN public.bf_parties p ON p.cafe_id=d.cafe_id AND p.id=d.party_id LEFT JOIN public.bf_invoice_extensions e ON e.cafe_id=d.cafe_id AND e.document_id=d.id LEFT JOIN public.bf_staff st ON st.cafe_id=d.cafe_id AND st.user_id=d.created_by CROSS JOIN LATERAL(SELECT brand_finance_private.document_state(c,d.id) state)x WHERE d.cafe_id=c AND d.kind=CASE s WHEN 'sales' THEN 'sale' ELSE 'purchase' END;RETURN;
 ELSIF s IN('sales-lines','purchase-lines') THEN
  RETURN QUERY SELECT erp_reports_private.fact(l.id::text,(d.created_at AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('number',d.number,'product',l.name,'productId',coalesce(to_jsonb(l)->>'inventory_item_id',l.product_id::text,l.item_id::text),'category',coalesce(cat.name,icat.name,''),'categoryId',coalesce(cat.id,icat.id),'warehouse',coalesce(w.name,''),'warehouseId',d.warehouse_id,'customer',CASE WHEN p.kind='customer' THEN p.name ELSE '' END,'customerId',CASE WHEN p.kind='customer' THEN p.id END,'supplier',CASE WHEN p.kind='supplier' THEN p.name ELSE '' END,'supplierId',CASE WHEN p.kind='supplier' THEN p.id END,'employeeId',d.created_by,'employee',coalesce(st.name,''),'kind',d.kind,'quantity',sign*l.quantity,'net',sign*l.net,'tax',sign*l.tax,'amount',sign*(l.net+l.tax),'cost',CASE WHEN l.cost_status IN('unknown','untracked') OR l.cost_status='legacy' AND l.cost=0 THEN NULL ELSE sign*coalesce((to_jsonb(l)->>'allocated_cost')::numeric,l.cost) END,'profit',CASE WHEN l.cost_status IN('unknown','untracked') OR l.cost_status='legacy' AND l.cost=0 THEN NULL ELSE sign*(l.net-coalesce((to_jsonb(l)->>'allocated_cost')::numeric,l.cost)) END,'unit',coalesce(to_jsonb(l)->>'unit_label',''),'href',CASE s WHEN 'sales-lines' THEN '/dashboard/finance?section=sales&view=invoice&invoice=' ELSE '/dashboard/system/purchases/invoices/' END||coalesce(d.reference_id,d.id)::text)||erp_reports_private.document_branch(c,to_jsonb(d)))
  FROM public.bf_document_lines l JOIN public.bf_documents d ON d.cafe_id=l.cafe_id AND d.id=l.document_id LEFT JOIN public.bf_documents original ON original.cafe_id=d.cafe_id AND original.id=d.reference_id LEFT JOIN public.bf_parties p ON p.cafe_id=d.cafe_id AND p.id=d.party_id LEFT JOIN public.menu_products product ON product.cafe_id=l.cafe_id AND product.id=l.product_id LEFT JOIN public.menu_categories cat ON cat.cafe_id=product.cafe_id AND cat.id=product.category_id LEFT JOIN public.erp_inventory_items item ON item.cafe_id=l.cafe_id AND item.item_id=coalesce(nullif(to_jsonb(l)->>'inventory_item_id','')::uuid,l.item_id) LEFT JOIN public.erp_inventory_catalogs icat ON icat.cafe_id=item.cafe_id AND icat.id=item.category_id LEFT JOIN public.bf_warehouses w ON w.cafe_id=d.cafe_id AND w.id=d.warehouse_id LEFT JOIN public.bf_staff st ON st.cafe_id=d.cafe_id AND st.user_id=d.created_by CROSS JOIN LATERAL(SELECT CASE WHEN d.kind='refund' THEN -1 ELSE 1 END sign)x WHERE l.cafe_id=c AND(d.kind=CASE s WHEN 'sales-lines' THEN 'sale' ELSE 'purchase' END OR d.kind='refund' AND original.kind=CASE s WHEN 'sales-lines' THEN 'sale' ELSE 'purchase' END);RETURN;
 ELSIF s IN('journal','cash-flow','sales-payments','purchase-payments') THEN
  RETURN QUERY SELECT erp_reports_private.fact(j.id::text,(d.created_at AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('number',d.number,'name',a.name,'account',a.name,'accountId',a.id,'accountKind',a.kind,'accountClass',CASE WHEN a.kind IN('expense','revenue') THEN 'income' WHEN a.kind IN('vat_input','vat_output') THEN 'tax' ELSE 'balance' END,'kind',d.kind,'note',d.note,'customer',CASE WHEN p.kind='customer' THEN p.name ELSE '' END,'customerId',CASE WHEN p.kind='customer' THEN p.id END,'supplier',CASE WHEN p.kind='supplier' THEN p.name ELSE '' END,'supplierId',CASE WHEN p.kind='supplier' THEN p.id END,'employeeId',d.created_by,'employee',coalesce(st.name,''),'debit',j.debit,'credit',j.credit,'balance',j.debit-j.credit,'received',j.debit,'issued',j.credit,'profit',CASE WHEN s='cash-flow' THEN CASE WHEN d.kind IN('sale','purchase','settlement','expense','receipt','refund') THEN j.debit-j.credit ELSE 0 END ELSE CASE WHEN a.kind IN('expense','revenue') THEN j.credit-j.debit ELSE 0 END END,'amount',CASE WHEN s='purchase-payments' THEN j.credit-j.debit ELSE j.debit-j.credit END,'status','posted','href','/dashboard/system/accounting/reports')||erp_reports_private.document_branch(c,to_jsonb(d)))
  FROM public.bf_journal j JOIN public.bf_documents d ON d.cafe_id=j.cafe_id AND d.id=j.document_id JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id LEFT JOIN public.bf_parties p ON p.cafe_id=d.cafe_id AND p.id=coalesce(j.party_id,d.party_id) LEFT JOIN public.bf_documents parent ON parent.cafe_id=d.cafe_id AND parent.id=d.reference_id LEFT JOIN public.bf_staff st ON st.cafe_id=d.cafe_id AND st.user_id=d.created_by WHERE j.cafe_id=c AND(s='journal' OR a.kind IN('cash','bank','pos') AND(s='cash-flow' OR s='sales-payments' AND(d.kind='sale' OR d.kind IN('settlement','refund') AND parent.kind='sale') OR s='purchase-payments' AND(d.kind='purchase' OR d.kind IN('settlement','refund') AND parent.kind='purchase')));RETURN;
 ELSIF s='accounts' THEN
  RETURN QUERY SELECT erp_reports_private.fact(a.id::text,NULL,jsonb_build_object('account',a.name,'accountId',a.id,'number',a.code,'name',a.name,'accountKind',a.kind,'accountClass',CASE WHEN a.kind IN('expense','revenue') THEN 'income' WHEN a.kind IN('vat_input','vat_output') THEN 'tax' ELSE 'balance' END,'opening',coalesce(sum(j.debit-j.credit) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date<f),0),'debit',coalesce(sum(j.debit) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN f AND t),0),'credit',coalesce(sum(j.credit) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN f AND t),0),'closing',coalesce(sum(j.debit-j.credit),0),'balance',CASE WHEN a.kind IN('revenue','expense') THEN coalesce(sum(j.credit-j.debit) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN f AND t),0) ELSE coalesce(sum(j.debit-j.credit),0) END,'status',CASE WHEN a.active THEN 'active' ELSE 'inactive' END))
  FROM public.bf_accounts a LEFT JOIN(public.bf_journal j JOIN public.bf_documents d ON d.cafe_id=j.cafe_id AND d.id=j.document_id AND(d.created_at AT TIME ZONE 'Asia/Riyadh')::date<=t) ON j.cafe_id=a.cafe_id AND j.account_id=a.id WHERE a.cafe_id=c AND NOT a.is_group GROUP BY a.id;RETURN;
 ELSIF s IN('customer-balances','supplier-balances') THEN
  RETURN QUERY SELECT erp_reports_private.fact(p.id::text,NULL,jsonb_build_object('name',p.name,'customer',CASE WHEN p.kind='customer' THEN p.name ELSE '' END,'customerId',CASE WHEN p.kind='customer' THEN p.id END,'supplier',CASE WHEN p.kind='supplier' THEN p.name ELSE '' END,'supplierId',CASE WHEN p.kind='supplier' THEN p.id END,'opening',coalesce(sum(CASE p.kind WHEN 'customer' THEN j.debit-j.credit ELSE j.credit-j.debit END) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date<f),0),'debit',coalesce(sum(j.debit) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN f AND t),0),'credit',coalesce(sum(j.credit) FILTER(WHERE(d.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN f AND t),0),'closing',coalesce(sum(CASE p.kind WHEN 'customer' THEN j.debit-j.credit ELSE j.credit-j.debit END),0),'status',CASE WHEN p.active THEN 'active' ELSE 'inactive' END))
  FROM public.bf_parties p LEFT JOIN(public.bf_journal j JOIN public.bf_documents d ON d.cafe_id=j.cafe_id AND d.id=j.document_id AND(d.created_at AT TIME ZONE 'Asia/Riyadh')::date<=t JOIN public.bf_accounts a ON a.cafe_id=j.cafe_id AND a.id=j.account_id AND a.kind=CASE s WHEN 'customer-balances' THEN 'receivable' ELSE 'payable' END) ON j.cafe_id=p.cafe_id AND j.party_id=p.id WHERE p.cafe_id=c AND p.kind=CASE s WHEN 'customer-balances' THEN 'customer' ELSE 'supplier' END GROUP BY p.id;RETURN;
 ELSIF s IN('expenses','receipts') THEN
  RETURN QUERY SELECT erp_reports_private.fact(v.id::text,(v.payload->>'date')::date,jsonb_build_object('number',v.code,'name',v.payload->>'note','note',v.payload->>'note','category',coalesce(cat.name,''),'categoryId',v.category_id,'customer',CASE WHEN p.kind='customer' THEN p.name ELSE '' END,'customerId',CASE WHEN p.kind='customer' THEN p.id END,'supplier',CASE WHEN p.kind='supplier' THEN p.name ELSE '' END,'supplierId',CASE WHEN p.kind='supplier' THEN p.id END,'account',a.name,'accountId',a.id,'net',(v.payload#>>'{calculation,net}')::numeric,'tax',(v.payload#>>'{calculation,tax}')::numeric,'amount',(v.payload#>>'{calculation,total}')::numeric,'status',v.status,'currency','SAR','href','/dashboard/system/finance/'||CASE v.kind WHEN 'expense' THEN 'expenses' ELSE 'receipts' END||'/'||v.id)) FROM public.erp_finance_vouchers v LEFT JOIN public.erp_finance_categories cat ON cat.cafe_id=v.cafe_id AND cat.id=v.category_id LEFT JOIN public.bf_parties p ON p.cafe_id=v.cafe_id AND p.id=v.party_id JOIN public.bf_accounts a ON a.cafe_id=v.cafe_id AND a.id=(v.payload->>'cashAccountId')::uuid WHERE v.cafe_id=c AND v.document_id IS NOT NULL AND v.kind=CASE s WHEN 'expenses' THEN 'expense' ELSE 'receipt' END;
  RETURN QUERY SELECT erp_reports_private.fact(v.id::text||'-reversal',(d.created_at AT TIME ZONE 'Asia/Riyadh')::date,jsonb_build_object('number',v.code,'name',d.note,'note',d.note,'category',coalesce(cat.name,''),'categoryId',v.category_id,'account',a.name,'accountId',a.id,'net',-(v.payload#>>'{calculation,net}')::numeric,'tax',-(v.payload#>>'{calculation,tax}')::numeric,'amount',-(v.payload#>>'{calculation,total}')::numeric,'status','reversal','currency','SAR','href','/dashboard/system/finance/'||CASE v.kind WHEN 'expense' THEN 'expenses' ELSE 'receipts' END||'/'||v.id)) FROM public.erp_finance_vouchers v JOIN public.bf_documents d ON d.cafe_id=v.cafe_id AND d.id=v.reversal_id LEFT JOIN public.erp_finance_categories cat ON cat.cafe_id=v.cafe_id AND cat.id=v.category_id JOIN public.bf_accounts a ON a.cafe_id=v.cafe_id AND a.id=(v.payload->>'cashAccountId')::uuid WHERE v.cafe_id=c AND v.kind=CASE s WHEN 'expenses' THEN 'expense' ELSE 'receipt' END;RETURN QUERY SELECT * FROM erp_reports_private.legacy_voucher_facts(c,s,f,t);RETURN;
 END IF;RAISE EXCEPTION 'مصدر الحقائق المالية غير معروف';
END $$;
CREATE FUNCTION erp_reports_private.numeric_fields() RETURNS text[] LANGUAGE sql IMMUTABLE SET search_path='' AS $$SELECT ARRAY['amount','net','tax','paid','outstanding','refunded','cost','profit','quantity','debit','credit','balance','opening','closing','hours','days','scheduledHours','lateMinutes','earlyMinutes','overtimeHours','count','current','age30','age60','age90','ageOlder','estimatedCost','cashPaid','budget','remaining','received','issued','turnover','average','required','present','missing','value','cashMovement']::text[]$$;
CREATE FUNCTION erp_reports_private.enrich(r jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$DECLARE d date:=(r->>'date')::date;BEGIN IF d IS NULL THEN RETURN r;END IF;RETURN r||jsonb_build_object('year',to_char(d,'YYYY'),'quarter',to_char(d,'YYYY')||'-Q'||extract(quarter FROM d)::text,'month',to_char(d,'YYYY-MM'),'week',to_char(d,'IYYY-IW'));END $$;
CREATE FUNCTION erp_reports_private.aggregate_metric(records jsonb[],field text,source text) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$DECLARE a numeric;b numeric;BEGIN
 IF field IN('average','turnover') AND source='stock-turnover' THEN SELECT coalesce(sum((r->>'opening')::numeric+(r->>'closing')::numeric),0)/2,coalesce(sum((r->>'issued')::numeric),0) INTO a,b FROM unnest(records)r;RETURN CASE WHEN field='average' THEN to_jsonb(a) WHEN a>0 THEN to_jsonb(b/a) ELSE 'null'::jsonb END;END IF;
 IF field='average' AND source='stock' THEN IF EXISTS(SELECT 1 FROM unnest(records)r WHERE r->'value'='null'::jsonb) THEN RETURN 'null'::jsonb;END IF;SELECT sum((r->>'value')::numeric),sum((r->>'closing')::numeric) INTO a,b FROM unnest(records)r;RETURN CASE WHEN b<>0 THEN to_jsonb(a/b) ELSE 'null'::jsonb END;END IF;
 IF EXISTS(SELECT 1 FROM unnest(records)r WHERE r?field AND r->field='null'::jsonb) THEN RETURN 'null'::jsonb;END IF;RETURN to_jsonb((SELECT coalesce(sum((r->>field)::numeric),0) FROM unnest(records)r WHERE jsonb_typeof(r->field)='number'));
END $$;
CREATE FUNCTION erp_reports_private.condition(r jsonb,p jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$DECLARE field text:=p->>'field';op text:=p->>'operator';v text:=r->>field;wanted text:=p->>'value';BEGIN
 IF op='empty' THEN RETURN coalesce(v,'')='';ELSIF op='not_empty' THEN RETURN coalesce(v,'')<>'';ELSIF op='eq' THEN RETURN coalesce(v,'')=coalesce(wanted,'');ELSIF op='neq' THEN RETURN coalesce(v,'')<>coalesce(wanted,'');ELSIF op='contains' THEN RETURN position(lower(coalesce(wanted,'')) IN lower(coalesce(v,'')))>0;ELSIF op='starts' THEN RETURN left(lower(coalesce(v,'')),length(wanted))=lower(wanted);ELSIF op='ends' THEN RETURN right(lower(coalesce(v,'')),length(wanted))=lower(wanted);ELSIF op IN('gte','lte') THEN IF field=ANY(erp_reports_private.numeric_fields()) THEN IF wanted!~'^-?[0-9]+([.][0-9]+)?$' THEN RAISE EXCEPTION 'قيمة شرط التقرير ليست رقمًا';END IF;RETURN CASE op WHEN 'gte' THEN(v::numeric>=wanted::numeric) ELSE(v::numeric<=wanted::numeric) END;END IF;RETURN CASE op WHEN 'gte' THEN v>=wanted ELSE v<=wanted END;END IF;RAISE EXCEPTION 'معامل شرط غير صالح';
END $$;
CREATE FUNCTION erp_reports_private.matches(r jsonb,q jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path='' AS $$DECLARE k text;v text;condition jsonb;matched boolean;any_match boolean:=false;BEGIN
 FOR k,v IN SELECT key,value FROM jsonb_each_text(coalesce(q->'filters','{}')) LOOP IF v<>'' AND coalesce(r->>k,'')<>v THEN RETURN false;END IF;END LOOP;
 FOR condition IN SELECT * FROM jsonb_array_elements(coalesce(q->'conditions','[]')) LOOP matched:=coalesce(erp_reports_private.condition(r,condition),false);IF q->>'conditionMode'='all' AND NOT matched THEN RETURN false;END IF;any_match:=any_match OR matched;END LOOP;
 RETURN q->>'conditionMode'<>'any' OR jsonb_array_length(coalesce(q->'conditions','[]'))=0 OR any_match;
END $$;
CREATE FUNCTION erp_reports_private.validate_query(q jsonb) RETURNS void LANGUAGE plpgsql STABLE SET search_path='' AS $$DECLARE allowed jsonb;column_name text;condition jsonb;BEGIN
 SELECT columns||'["date","year","quarter","month","week"]'::jsonb INTO allowed FROM erp_reports_private.sources WHERE id=q->>'source';IF NOT FOUND THEN RAISE EXCEPTION 'مصدر التقرير غير متاح';END IF;
 IF jsonb_typeof(q) IS DISTINCT FROM 'object' OR octet_length(q::text)>50000 OR jsonb_typeof(q->'columns') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'columns') NOT BETWEEN 1 AND 40 OR jsonb_typeof(q->'groupBy') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'groupBy')>4 OR jsonb_typeof(q->'conditions') IS DISTINCT FROM 'array' OR jsonb_array_length(q->'conditions')>30 OR jsonb_typeof(q->'filters') IS DISTINCT FROM 'object' OR jsonb_typeof(q->'summary') IS DISTINCT FROM 'boolean' OR jsonb_typeof(q->'descending') IS DISTINCT FROM 'boolean' OR coalesce(q->>'conditionMode','') NOT IN('all','any') OR(q->>'from')::date IS NULL OR(q->>'to')::date IS NULL OR NOT isfinite((q->>'from')::date) OR NOT isfinite((q->>'to')::date) OR(q->>'to')::date<(q->>'from')::date OR(q->>'to')::date-(q->>'from')::date>3660 OR coalesce((q->>'offset')::integer,-1) NOT BETWEEN 0 AND 10000000 OR coalesce((q->>'limit')::integer,0) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'راجع فترة التقرير والأعمدة والمرشحات';END IF;
 FOR column_name IN SELECT jsonb_array_elements_text((q->'columns')||(q->'groupBy')||jsonb_build_array(q->>'sortBy')) LOOP IF NOT(allowed?column_name) THEN RAISE EXCEPTION 'عمود التقرير غير متاح للمصدر';END IF;END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements_text(q->'groupBy')v WHERE v=ANY(erp_reports_private.numeric_fields())) OR jsonb_array_length(q->'columns')<>(SELECT count(DISTINCT x) FROM jsonb_array_elements_text(q->'columns')x) OR jsonb_array_length(q->'groupBy')<>(SELECT count(DISTINCT x) FROM jsonb_array_elements_text(q->'groupBy')x) THEN RAISE EXCEPTION 'الأعمدة أو التجميعات مكررة أو غير صالحة';END IF;
 FOR condition IN SELECT * FROM jsonb_array_elements(q->'conditions') LOOP IF jsonb_typeof(condition) IS DISTINCT FROM 'object' OR jsonb_typeof(condition->'field') IS DISTINCT FROM 'string' OR jsonb_typeof(condition->'value') IS DISTINCT FROM 'string' OR NOT(allowed?(condition->>'field')) OR coalesce(condition->>'operator','') NOT IN('eq','neq','contains','starts','ends','gte','lte','empty','not_empty') OR length(coalesce(condition->>'value',''))>1000 THEN RAISE EXCEPTION 'شرط التقرير غير صالح';END IF;END LOOP;
 IF jsonb_typeof(q->'sortBy') IS DISTINCT FROM 'string' OR NOT(allowed?(q->>'sortBy')) THEN RAISE EXCEPTION 'حدد عمود ترتيب صالحًا';END IF;
 FOR column_name IN SELECT jsonb_object_keys(q->'filters') LOOP IF NOT(allowed?column_name) AND column_name NOT IN('accountClass','accountKind','source','expiry','residency','available','kind','status') THEN RAISE EXCEPTION 'مرشح التقرير غير متاح للمصدر';END IF;IF jsonb_typeof(q->'filters'->column_name) IS DISTINCT FROM 'string' OR length(q->'filters'->>column_name)>1000 THEN RAISE EXCEPTION 'قيمة مرشح التقرير غير صالحة';END IF;END LOOP;
 IF(q->>'summary')::boolean AND EXISTS(SELECT 1 FROM jsonb_array_elements_text(q->'columns')k WHERE NOT(k=ANY(erp_reports_private.numeric_fields())) AND NOT(q->'groupBy'?k)) THEN RAISE EXCEPTION 'أعمدة الملخص يجب أن تكون قيمًا رقمية أو حقول التجميع';END IF;
END $$;
CREATE FUNCTION erp_reports_private.facts(c uuid,s text,f date,t date) RETURNS SETOF jsonb LANGUAGE plpgsql SET search_path='' AS $$BEGIN
 PERFORM erp_reports_private.authorize_source(c,s);
 IF s IN('sales','sales-lines','sales-payments','purchase-documents','purchase-lines','purchase-payments','journal','accounts','cash-flow','customer-balances','supplier-balances','expenses','receipts') THEN RETURN QUERY SELECT * FROM erp_reports_private.financial_facts(c,s,f,t);
 ELSIF s IN('customers','suppliers','customer-credits','credit-charges','credit-usages','memberships','membership-renewals','customer-aging','supplier-aging') THEN RETURN QUERY SELECT * FROM erp_reports_private.customer_facts(c,s,f,t);
 ELSIF s IN('employees','employee-documents','employee-compliance','attendance','leave-balance','shifts','contracts','payslips','loans') THEN RETURN QUERY SELECT * FROM erp_reports_private.employee_facts(c,s,f,t);
 ELSIF s IN('stock','stock-movements','stock-aging','stock-turnover','stock-requests','manufacturing','assets') THEN RETURN QUERY SELECT * FROM erp_reports_private.inventory_facts(c,s,f,t);
 ELSE RETURN QUERY SELECT * FROM erp_reports_private.operational_facts(c,s,f,t);END IF;
END $$;
CREATE FUNCTION erp_reports_private.visible_source(c uuid,s text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path='' AS $$BEGIN PERFORM erp_reports_private.authorize_source(c,s);RETURN true;EXCEPTION WHEN insufficient_privilege THEN RETURN false;END $$;
CREATE FUNCTION public.erp_reports_read(p_cafe_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE role text;BEGIN
 role:=erp_reports_private.authorize(p_cafe_id);RETURN erp_access_private.mask_snapshot(p_cafe_id,'reports',jsonb_build_object('catalog',coalesce((SELECT jsonb_agg(definition ORDER BY family,title) FROM erp_reports_private.catalog WHERE erp_reports_private.visible_source(p_cafe_id,source)),'[]'),'sources',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'title',title,'columns',(SELECT jsonb_agg(DISTINCT k) FROM jsonb_array_elements(columns||'["date","year","quarter","month","week"]'::jsonb)k)) ORDER BY title) FROM erp_reports_private.sources WHERE erp_reports_private.visible_source(p_cafe_id,id)),'[]'),'saved',coalesce((SELECT jsonb_agg(definition||jsonb_build_object('id',id,'revision',revision,'name',name,'family',family,'createdAt',created_at,'updatedAt',updated_at) ORDER BY updated_at DESC) FROM public.erp_saved_reports WHERE cafe_id=p_cafe_id AND erp_reports_private.visible_source(p_cafe_id,definition#>>'{query,source}')),'[]'),'canWrite',role NOT IN('auditor','warehouse')));
END $$;
CREATE FUNCTION erp_reports_private.run(p_cafe_id uuid,p_query jsonb,p_export boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE q jsonb:=p_query;answer jsonb;BEGIN
 PERFORM erp_reports_private.authorize_source(p_cafe_id,q->>'source');PERFORM erp_reports_private.validate_query(q);IF p_export THEN q:=q||'{"limit":50001,"offset":0}'::jsonb;END IF;
 WITH base AS MATERIALIZED(SELECT erp_reports_private.enrich(x) r FROM erp_reports_private.facts(p_cafe_id,q->>'source',(q->>'from')::date,(q->>'to')::date)x WHERE x->>'date' IS NULL OR(x->>'date')::date BETWEEN(q->>'from')::date AND(q->>'to')::date),
 filtered AS MATERIALIZED(SELECT r FROM base WHERE erp_reports_private.matches(r,q)),
 grouped AS(SELECT coalesce((SELECT jsonb_object_agg(k,r->k) FROM jsonb_array_elements_text(q->'groupBy')k),'{}') dimensions,array_agg(r) records FROM filtered GROUP BY 1),
 grouped_rows AS(SELECT dimensions||coalesce((SELECT jsonb_object_agg(k,erp_reports_private.aggregate_metric(records,k,q->>'source')) FROM jsonb_array_elements_text(q->'columns')k WHERE k=ANY(erp_reports_private.numeric_fields())),'{}') r FROM grouped),
 results AS MATERIALIZED(SELECT r FROM filtered WHERE NOT(q->>'summary')::boolean UNION ALL SELECT r FROM grouped_rows WHERE(q->>'summary')::boolean),
 page AS(SELECT r FROM results ORDER BY CASE WHEN NOT(q->>'descending')::boolean AND q->>'sortBy'=ANY(erp_reports_private.numeric_fields()) THEN(r->>(q->>'sortBy'))::numeric END ASC NULLS LAST,CASE WHEN(q->>'descending')::boolean AND q->>'sortBy'=ANY(erp_reports_private.numeric_fields()) THEN(r->>(q->>'sortBy'))::numeric END DESC NULLS LAST,CASE WHEN NOT(q->>'descending')::boolean THEN r->>(q->>'sortBy') END ASC NULLS LAST,CASE WHEN(q->>'descending')::boolean THEN r->>(q->>'sortBy') END DESC NULLS LAST,r->>'id' LIMIT(q->>'limit')::integer OFFSET(q->>'offset')::integer),
 totals AS(SELECT coalesce(jsonb_object_agg(k,erp_reports_private.aggregate_metric((SELECT array_agg(r) FROM filtered),k,q->>'source')),'{}') values FROM jsonb_array_elements_text(q->'columns')k WHERE k=ANY(erp_reports_private.numeric_fields())),
 options AS(SELECT coalesce(jsonb_object_agg(k,items),'{}') values FROM(SELECT k,(SELECT coalesce(jsonb_agg(v ORDER BY v),'[]') FROM(SELECT DISTINCT r->>k v FROM base WHERE coalesce(r->>k,'')<>'' ORDER BY 1 LIMIT 500)x)items FROM jsonb_array_elements_text((SELECT columns FROM erp_reports_private.sources WHERE id=q->>'source'))k WHERE NOT(k=ANY(erp_reports_private.numeric_fields())) AND k NOT IN('note','phone','email'))x)
 SELECT jsonb_build_object('rows',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r->>'id','href',r->>'href')||coalesce((SELECT jsonb_object_agg(k,r->k) FROM jsonb_array_elements_text(q->'columns')k),'{}')) FROM page),'[]'),'total',(SELECT count(*) FROM results),'totals',(SELECT values FROM totals),'options',(SELECT values FROM options),'from',q->>'from','to',q->>'to','generatedAt',clock_timestamp(),'basis','real_source_records','hasMore',(SELECT count(*) FROM results)>(q->>'offset')::integer+(q->>'limit')::integer) INTO answer;IF p_export AND(answer->>'total')::integer>50000 THEN RAISE EXCEPTION USING MESSAGE='Report export exceeds 50000 rows',ERRCODE='54000';END IF;RETURN answer;
END $$;
CREATE FUNCTION public.erp_report_run(p_cafe_id uuid,p_query jsonb) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT erp_reports_private.run(p_cafe_id,p_query,false)$$;
CREATE FUNCTION public.erp_report_export(p_cafe_id uuid,p_query jsonb) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$SELECT erp_reports_private.run(p_cafe_id,p_query,true)$$;
CREATE FUNCTION public.erp_reports_write(p_cafe_id uuid,p_action text,p_data jsonb,p_request_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$DECLARE old public.erp_saved_reports;prior erp_reports_private.requests;i uuid:=coalesce((p_data->>'id')::uuid,gen_random_uuid());cmd jsonb:=jsonb_build_object('action',p_action,'data',p_data);result jsonb;BEGIN
 PERFORM erp_reports_private.authorize(p_cafe_id,CASE p_action WHEN 'delete' THEN 'delete' ELSE CASE WHEN p_data->>'id' IS NULL THEN 'create' ELSE 'update' END END);
 IF p_request_id IS NULL OR p_action NOT IN('save','delete') OR jsonb_typeof(p_data) IS DISTINCT FROM 'object' OR octet_length(p_data::text)>60000 THEN RAISE EXCEPTION 'طلب التقرير غير صالح';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(p_cafe_id::text,67961));SELECT * INTO prior FROM erp_reports_private.requests WHERE cafe_id=p_cafe_id AND id=p_request_id;IF FOUND THEN IF prior.actor<>auth.uid() OR prior.command<>cmd THEN RAISE EXCEPTION 'معرف الطلب مستخدم ببيانات أخرى';END IF;RETURN prior.result;END IF;
 IF p_data->>'id' IS NOT NULL THEN SELECT * INTO old FROM public.erp_saved_reports WHERE cafe_id=p_cafe_id AND id=i FOR UPDATE;IF NOT FOUND OR old.revision IS DISTINCT FROM(p_data->>'revision')::integer THEN RAISE EXCEPTION 'تغير التقرير أعد تحميله' USING ERRCODE='40001';END IF;PERFORM erp_reports_private.authorize_source(p_cafe_id,old.definition#>>'{query,source}');END IF;
 IF p_action='delete' THEN IF old.id IS NULL THEN RAISE EXCEPTION 'التقرير غير موجود';END IF;DELETE FROM public.erp_saved_reports WHERE cafe_id=p_cafe_id AND id=i;
 ELSE
  PERFORM erp_reports_private.authorize_source(p_cafe_id,p_data#>>'{query,source}');PERFORM erp_reports_private.validate_query(p_data->'query');IF length(btrim(coalesce(p_data->>'name',''))) NOT BETWEEN 1 AND 150 OR coalesce(p_data->>'family','') NOT IN('sales','purchases','accounting','cheques','manufacturing','sms','credits','employees','memberships','rentals','workflows','work-orders','customers','inventory','time','ai','activity') OR coalesce(p_data#>>'{chart,kind}','') NOT IN('none','bar','line','area','pie') THEN RAISE EXCEPTION 'راجع اسم التقرير ومخططه';END IF;
  IF jsonb_typeof(p_data#>'{chart,showLegend}') IS DISTINCT FROM 'boolean' OR jsonb_typeof(p_data#>'{chart,stacked}') IS DISTINCT FROM 'boolean' OR(p_data#>>'{chart,kind}'<>'none' AND(NOT(p_data#>'{query,columns}'?(p_data#>>'{chart,label}')) OR NOT(p_data#>'{query,columns}'?(p_data#>>'{chart,value}')) OR NOT(p_data#>>'{chart,value}'=ANY(erp_reports_private.numeric_fields())))) THEN RAISE EXCEPTION 'اختر حقول المخطط من أعمدة التقرير المحددة';END IF;
  INSERT INTO public.erp_saved_reports(cafe_id,id,name,family,definition,created_by) VALUES(p_cafe_id,i,btrim(p_data->>'name'),p_data->>'family',p_data-'id'-'revision'-'name'-'family',auth.uid()) ON CONFLICT(cafe_id,id) DO UPDATE SET name=excluded.name,family=excluded.family,definition=excluded.definition,revision=erp_saved_reports.revision+1,updated_at=now();
 END IF;result:=jsonb_build_object('id',i);INSERT INTO public.erp_report_events(cafe_id,record_id,action,actor) VALUES(p_cafe_id,i,p_action,auth.uid());INSERT INTO erp_reports_private.requests VALUES(p_cafe_id,p_request_id,auth.uid(),cmd,result);RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.erp_reports_read(uuid),public.erp_report_run(uuid,jsonb),public.erp_report_export(uuid,jsonb),public.erp_reports_write(uuid,text,jsonb,uuid) FROM PUBLIC,anon,service_role;
GRANT EXECUTE ON FUNCTION public.erp_reports_read(uuid),public.erp_report_run(uuid,jsonb),public.erp_report_export(uuid,jsonb),public.erp_reports_write(uuid,text,jsonb,uuid) TO authenticated;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA erp_reports_private FROM PUBLIC,anon,authenticated,service_role;
REVOKE ALL ON ALL TABLES IN SCHEMA erp_reports_private FROM PUBLIC,anon,authenticated,service_role;
COMMIT;
